#!/usr/bin/env bash
# Builds the shared documentation indexes from their fragment directories.
#
# Every line of scripts/docs-index.conf is "<fragment dir> <generated file>",
# relative to the repository root. A generated file is the fragments of its
# directory (every *.md, sorted by name in the C locale), joined by a blank line,
# or by a single newline between two table rows or two list items (a
# fragment that starts with a list item followed by one that does), after a
# do-not-edit comment.
#
# Feature work adds or edits its own fragment and never edits a generated file:
# a GitHub Action regenerates them on main after each merge.
#
#   scripts/docs-index.sh           regenerate every generated file
#   scripts/docs-index.sh --check   exit 1 if a generated file is out of date
#   scripts/docs-index.sh --outputs print the generated files' paths
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
conf="$root/scripts/docs-index.conf"
mode="${1:-write}"

generate() { # <fragment dir> <generated path shown in the comment>
	local dir="$1" out="$2"
	printf '<!-- Generated by scripts/docs-index.sh from %s/: do not edit this file, add or edit a fragment there (see documentation/Fragments.md). -->\n\n' "$dir"
	local files
	files=$(cd "$root/$dir" && LC_ALL=C ls -1 -- *.md | grep -v '^README\.md$' | LC_ALL=C sort)
	(cd "$root/$dir" && awk '
		FNR == 1 { started = 1; first = 1 }
		{ sub(/\r$/, "") }
		first {
			if (NR > 1) {
				joined = (prev ~ /^\|/ && $0 ~ /^\|/) || (head ~ /^([-*]|[0-9]+\.) / && $0 ~ /^([-*]|[0-9]+\.) /)
				printf "%s", (joined ? "\n" : "\n\n")
			}
			first = 0
			pending = ""
			printf "%s", $0
			prev = $0
			head = $0
			next
		}
		/^[ \t]*$/ { pending = pending "\n"; next }
		{ printf "%s\n%s", pending, $0; pending = ""; prev = $0 }
		END { printf "\n" }
	' $files)
}

status=0
while read -r dir out; do
	[[ -z "${dir:-}" || "$dir" == \#* ]] && continue
	case "$mode" in
	--outputs) echo "$out" ;;
	--check)
		if ! diff -q <(generate "$dir" "$out") "$root/$out" >/dev/null 2>&1; then
			echo "out of date: $out (run scripts/docs-index.sh)" >&2
			status=1
		fi ;;
	write) generate "$dir" "$out" >"$root/$out.tmp" && mv "$root/$out.tmp" "$root/$out" ;;
	*) echo "usage: $0 [--check|--outputs]" >&2; exit 2 ;;
	esac
done <"$conf"
exit $status
